local config = {
  ui_story_30790101_1_dialog_content = "Baiklah. Aku ukur bagian ini dulu...",
  ui_story_30790101_2_dialog_content = "Cukup tinggi. Coba aku berjinjit.",
  ui_story_30790101_3_dialog_content = "Hah? Kau sedang apa, Michenny?",
  ui_story_30790101_4_dialog_content = "Seperti yang kau lihat, aku sedang \"<color=#FFB400>mengukur</color>\".",
  ui_story_30790101_5_dialog_content = "Yang adalah langkah penting sebelum \"<color=#FFB400>menghitung</color>\".",
  ui_story_30790101_6_dialog_content = "Pengukuran yang presisi yang dilakukan untuk \"menghitung\" nilai sejati segala sesuatu.",
  ui_story_30790101_7_option_content = "Lalu apa yang kau ukur?",
  ui_story_30790101_8_dialog_content = "Seperti yang bisa kau lihat, aku mengukur Soroz.",
  ui_story_30790101_9_dialog_content = "Soroz?!",
  ui_story_30790101_10_dialog_content = "Kenapa kau mengukurnya?",
  ui_story_30790101_11_dialog_content = "Karena aku perlu menghitung nilainya.",
  ui_story_30790101_12_option_content = "Apa yang kau hitung?",
  ui_story_30790101_13_dialog_content = "Aku menghitung nilai Soroz atas permintaan Vice.",
  ui_story_30790101_14_dialog_content = "Soroz?!",
  ui_story_30790101_15_dialog_content = "Kenapa kau menghitungnya?",
  ui_story_30790101_16_dialog_content = "Karena dengan begitu, saat seseorang terpeleset di lantai Soroz dan perlu menuntut ganti rugi pada Navigator, kita akan tahu jumlah kompensasi yang pantas.",
  ui_story_30790101_17_dialog_content = "A-apa?!",
  ui_story_30790101_18_dialog_content = "Tunggu, kita mulai dari awal. Kenapa kau menuntut ganti rugi padaku? Siapa yang terpeleset? Bagaimana itu terjadi?",
  ui_story_30790101_19_dialog_content = "Begini.",
  ui_story_30790101_20_dialog_content = "Karena Colossus ini terlalu bersih.",
  ui_story_30790101_21_dialog_content = "Lantai di lorong itu semulus cermin.",
  ui_story_30790101_22_dialog_content = "Itulah kenapa Vice terpeleset saat berjalan di sana.",
  ui_story_30790101_23_dialog_content = "Vice? Dia tidak apa-apa?",
  ui_story_30790101_24_dialog_content = "Sepertinya dia baik-baik saja secara fisik.",
  ui_story_30790101_25_dialog_content = "Tapi kudengar dia menggerutu tentang kesialannya. Dan kalau dia sakit gara-gara ini, dia akan meminta ganti rugi pada Navigator.",
  ui_story_30790101_26_dialog_content = "Aku?",
  ui_story_30790101_27_dialog_content = "Oh... Begini. Aku sedang lewat di lorong pagi ini saat melihat lantai itu sedikit kotor.",
  ui_story_30790101_28_dialog_content = "Jadi, aku mengepelnya sedikit.",
  ui_story_30790101_29_dialog_content = "Apa aku berlebihan dalam membersihkannya?",
  ui_story_30790101_30_dialog_content = "Bagaimana itu terjadi tidak jadi soal buatku. Aku hanya peduli pada \"penghitungan\" itu sendiri.",
  ui_story_30790101_31_dialog_content = "Karena ada anggota Soroz di sini, ada kemungkinan <color=#FFB400>seseorang meminta Navigator mengganti rugi atas kejadian terpeleset itu</color>...",
  ui_story_30790101_32_dialog_content = "Jadi, aku harus bersiap untuk \"menghitung\".",
  ui_story_30790101_33_dialog_content = "Yang adalah alasan aku \"mengukur\" Soroz.",
  ui_story_30790101_34_dialog_content = "Jadi, kalau Vice benar-benar ingin kau \"menghitung\" ganti ruginya, kau akan bisa membayarkan Nightium kepadanya berdasarkan ukuran Soroz.",
  ui_story_30790101_35_dialog_content = "Begitu rupanya. Masuk akal...",
  ui_story_30790101_36_dialog_content = "Eh, tunggu, itu tidak masuk akal sama sekali! Bagaimana bisa aku harus membayarkan Nightium berdasarkan ukuran Soroz?",
  ui_story_30790101_37_dialog_content = "Bukan soal ini masuk akal atau tidak... Berapa jumlah yang harus kubayarkan persisnya?!",
  ui_story_30790101_38_dialog_content = "Jangan khawatir. Aku akan mulai \"menghitung\" setelah \"mengukur\".",
  ui_story_30790101_39_dialog_content = "Berdasarkan tingkat <color=#FFB400>sepuluh Nightium</color> per <color=#FFB400>sentimeter</color>...",
  ui_story_30790101_40_dialog_content = "Berapa?!",
  ui_story_30790101_41_dialog_content = "Sepuluh Nightium per sentimeter.",
  ui_story_30790101_42_dialog_content = "Begini... Aku punya pertanyaan.",
  ui_story_30790101_43_option_content = "Apa jarak Lumopolis dan Illumina 1 cm?",
  ui_story_30790101_44_dialog_content = "Tidak, ini satu sentimeter pada penggaris.",
  ui_story_30790101_45_dialog_content = "Karena kau keturunan Caelestite, kau mungkin tidak punya pengetahuan umum tentang dunia luar.",
  ui_story_30790101_46_dialog_content = "Aku akan memberimu penggaris sehingga kau punya pemahaman praktis tentang konsep jarak.",
  ui_story_30790101_47_dialog_content = "Setelah itu, silahkan membayar kompensasi dengan tarif sepuluh Nightium per sentimeter.",
  ui_story_30790101_48_dialog_content = "Kenapa kau tidak membunuhku saja sekalian?",
  ui_story_30790101_49_option_content = "Apakah Nightium merupakan hasil imajinasi anak-anak?",
  ui_story_30790101_50_dialog_content = "Bukan, itu mata uang di Lumopolis.",
  ui_story_30790101_51_dialog_content = "Kau bisa menggunakannya untuk membeli makanan, air, pakaian, dan kebutuhan sehari-hari...",
  ui_story_30790101_52_dialog_content = "Nightium sangat ringan namun sangat berharga. Mereka dapat dibawa ke mana-mana.",
  ui_story_30790101_53_dialog_content = "Begini. Sepertinya aku tidak salah paham...",
  ui_story_30790101_54_dialog_content = "Jadi jika sepuluh Nightium per sentimeter adalah tingkatnya, mengingat seberapa besar Soroz...",
  ui_story_30790101_55_dialog_content = "Kau tahu? Bunuh saja aku.",
  ui_story_30790101_56_dialog_content = "Dengan kata lain, <color=#FFB400>menjatuhimu hukuman mati</color>?",
  ui_story_30790101_57_dialog_content = "Tunggu, itu membutuhkan penghitungan baru.",
  ui_story_30790101_58_dialog_content = "Sesuai dengan peraturan penghitungan, penghitungan saat ini menggantikan penghitungan sebelumnya karena sifatnya yang lebih mendesak.",
  ui_story_30790101_59_dialog_content = "... Apa? Penghitungan tentang apa lagi ini?",
  ui_story_30790101_60_dialog_content = "Tentang \"menghukum mati Navigator\". Setelah \"mengukur\", nilai yang telah dihasilkan adalah 0,01 Nightium...",
  ui_story_30790101_61_dialog_content = "Sekecil itu nilaiku?",
  ui_story_30790101_62_dialog_content = "Ya. Tapi sebelumnya, mohon bayar aku 0,01 Nightium.",
  ui_story_30790101_63_dialog_content = "Tunggu, bayar? Kau ingin aku membayarmu?",
  ui_story_30790101_64_dialog_content = "Kau ingin aku membayarmu 0,01 Nightium agar kau menjatuhiku hukuman mati?",
  ui_story_30790101_65_dialog_content = "Jadi, nilaiku sebenarnya negatif?",
  ui_story_30790101_66_dialog_content = "Betul. Menurut pengukuran dan penghitungan, nilai nyawa Navigator adalah negatif 0,01 Nightium.",
  ui_story_30790101_67_dialog_content = "Dan <color=#FFB400>menghukum mati Navigator</color> pada dasarnya adalah <color=#FFB400>mengambil nyawa Navigator</color>.",
  ui_story_30790101_68_dialog_content = "Menghukum mati Navigator sama dengan membeli nyawa Navigator dari Navigator.",
  ui_story_30790101_69_dialog_content = "Karena nilai nyawa Navigator adalah negatif 0,01 Nightium,",
  ui_story_30790101_70_dialog_content = "Navigator harus membayar orang yang memberinya hukuman mati sebesar 0,01 Nightium.",
  ui_story_30790101_71_dialog_content = "Oh, begitu..",
  ui_story_30790101_72_option_content = "Aku semurah itu, ya?",
  ui_story_30790101_73_dialog_content = "Menurut \"pengukuran\", iya.",
  ui_story_30790101_74_dialog_content = "Walau aku cukup bingung. Bagaimanapun, Navigator adalah Caelestite langka.",
  ui_story_30790101_75_dialog_content = "Eclipsite tidak langka, tapi kalau mereka di posisimu, kurasa mereka tidak harus membayarmu untuk memberi mereka hukuman mati.",
  ui_story_30790101_76_option_content = "Jadi, orang bisa menggunakan nyawaku untuk mencari uang?",
  ui_story_30790101_77_dialog_content = "Secara teoretis, iya.",
  ui_story_30790101_78_dialog_content = "Namun, karena nyawa Navigator hanya bisa dipakai satu kali...",
  ui_story_30790101_79_dialog_content = "Kalau orang lain ingin menggunakan nyawamu untuk mencari uang, kau harus memikirkan apakah manfaatnya sepadan atau tidak.",
  ui_story_30790101_80_dialog_content = [[
Toh, saat nyawamu hanya bernilai sekitar -0,01 Nightium, menggunakannya untuk hal yang tidak bermakna...
Dapat mengakibatkan penyesalan di masa depan.]],
  ui_story_30790101_81_dialog_content = "Kalau menggunakan nyawaku yang berharga ini sembarangan, aku jelas akan menyesal.",
  ui_story_30790101_82_dialog_content = "Tidak, apa kau yakin tidak ada yang salah dengan penghitungan ini?",
  ui_story_30790101_83_dialog_content = "Aku yakin. Penghitungan ini didasarkan pada <color=#FFB400>Eternal Balance</color>.",
  ui_story_30790101_85_dialog_content = "Menurut \"pengukuran\" Eternal Balance, nyawa Navigator adalah...",
  ui_story_30790101_86_dialog_content = "Tunggu!",
  ui_story_30790101_87_dialog_content = "Sepertinya ada yang kurang dari timbangan ini...",
  ui_story_30790101_88_dialog_content = "Di mana <color=#FFB400>pemberatnya</color>?",
  ui_story_30790101_89_dialog_content = "Pemberatnya?",
  ui_story_30790101_90_dialog_content = "Hm... Hah?!",
  ui_story_30790101_91_dialog_content = "Pemberatnya... Pemberatnya... Hilang!",
  ui_story_30790101_92_dialog_content = "Kalau begitu, cari! Kau ke mana saja?",
  ui_story_30790101_93_dialog_content = "Aku ke... ke...",
  ui_story_30790101_94_dialog_content = "Aku tidak ingat...",
  ui_story_30790101_95_dialog_content = "Oh, hai! Kau di sini, Michenny.",
  ui_story_30790101_96_dialog_content = "Sepertinya aku menemukan barangmu di lorong.",
  ui_story_30790101_97_dialog_content = "Ini milikmu, 'kan?",
  ui_story_30790101_99_dialog_content = "Pemberatnya!",
  ui_story_30790101_100_dialog_content = "Ya, aku tadi terpeleset di lorong...",
  ui_story_30790101_101_dialog_content = "Dan sebelum bisa berdiri, aku melihat Michenny berjalan mendekat.",
  ui_story_30790101_102_dialog_content = "Lantainya sangat licin, dan Michenny juga hampir terpeleset. Tapi dia sangat tangkas, jadi dia cuma sedikit sempoyongan sebelum berjalan lagi.",
  ui_story_30790101_103_dialog_content = "Setelah berdiri, aku menemukan ini di lantai.",
  ui_story_30790101_104_dialog_content = "Michenny mungkin menjatuhkannya.",
  ui_story_30790101_105_dialog_content = "Oh... Kau terpeleset dan tidak sengaja menjatuhkan pemberatmu.",
  ui_story_30790101_106_dialog_content = "Inikah alasan \"penghitunganmu\" aneh?",
  ui_story_30790101_107_dialog_content = "A-aneh?",
  ui_story_30790101_108_dialog_content = "Ya!",
  ui_story_30790101_X108_dialog_content = "Pasang lagi pemberatnya sekarang!",
  ui_story_30790101_109_dialog_content = "Kalau tidak, saya harus membayar Vice dengan tarif sepuluh Nightium per sentimeter!",
  ui_story_30790101_110_dialog_content = "Lalu, aku harus membayarmu 0,01 Nightium untuk dihukum mati!",
  ui_story_30790101_111_dialog_content = "Hah? Sepuluh Nightium per sentimeter... Kamu membayar aku?",
  ui_story_30790101_112_dialog_content = "Aku tidak tahu kenapa kau membayarku... Tapi bagaimana kalau kau membayarku dulu, baru setelah itu dia bisa memasang lagi pemberatnya?",
  ui_story_30790101_113_dialog_content = "Ayolah, Michenny! Pasang lagi pemberatnya!",
  ui_story_30790101_114_dialog_content = "O-oke.",
  ui_story_30790101_116_dialog_content = "Selesai.",
  ui_story_30790101_117_dialog_content = "Aku mengerti... Jadi, semua \"penghitungan\" dilakukan tanpa pemberat.",
  ui_story_30790101_118_dialog_content = "Artinya, aku harus mengulangnya...",
  ui_story_30790101_119_dialog_content = "Ya! Apakah aku benar-benar hanya bernilai minus 0,01 Nightium?",
  ui_story_30790101_120_dialog_content = "Nyawa Navigator sekarang senilai...",
  ui_story_30790101_121_dialog_content = "Oh, ini tidak bisa diukur dengan pemberat lagi.",
  ui_story_30790101_122_dialog_content = "Sepertinya nyawa Navigator tidak hanya bernilai negatif,",
  ui_story_30790101_123_dialog_content = "tapi malah salah satu yang paling berharga di dunia.",
  ui_story_30790101_124_dialog_content = "Sekarang baru benar!",
  ui_story_30790101_125_dialog_content = "Hah? Kau cuma perlu waktu sebentar untuk mengakui bahwa \"penghitungan\" yang baru kau lakukan bermasalah?",
  ui_story_30790101_126_dialog_content = "Michenny benar-benar beda. Kalau aku jadi dia, aku akan berusaha menutup-nutupinya.",
  ui_story_30790101_X126_dialog_content = "Kau juga cukup jujur tentang itu, Vice.",
  ui_story_30790101_127_dialog_content = "\"Penghitungan\" yang salah tidak bisa dimaafkan.",
  ui_story_30790101_128_dialog_content = "Segera setelah ditemukan masalah, penghitungan itu harus diralat seketika.",
  ui_story_30790101_129_dialog_content = "Ini jugalah etika kerja yang harus dipatuhi \"penghitung\".",
  ui_story_30790101_130_dialog_content = "Selanjutnya, aku akan menghitung ganti rugi yang harus dibayarkan Navigator kepada Vice.",
  ui_story_30790101_131_dialog_content = "Hah, jadi PlayerName benar-benar akan membayarku.",
  ui_story_30790101_132_dialog_content = "T-tidak, tidak perlu!",
  ui_story_30790101_133_dialog_content = "Pasang lagi pemberatmu. Sebagai pihak yang terlibat, menurutku \"penghitungan\" ini tidak perlu dilanjutkan...",
  ui_story_30790101_134_dialog_content = "Hah?",
  ui_story_30790101_135_dialog_content = "Betul. Daripada melakukan \"penghitungan\" yang tidak perlu seperti ini...",
  ui_story_30790101_136_dialog_content = "Bukannya kau lebih baik berfokus pada \"penghitungan\" yang ada persis di depanmu?",
  ui_story_30790101_137_dialog_content = "Di depanku?",
  ui_story_30790101_138_dialog_content = "Misalnya, Eternal Balance ada persis di depanmu, tapi kau bahkan tidak tahu kalau pemberatnya hilang.",
  ui_story_30790101_139_dialog_content = "... Aku mengerti.",
  ui_story_30790101_140_dialog_content = "Memang. Aku ceroboh.",
  ui_story_30790101_141_dialog_content = "Tidak, itu bukan ceroboh. Sebagai penghitung, aku pun pernah... melakukan kesalahan yang tak termaafkan.",
  ui_story_30790101_142_dialog_content = "Terima kasih, PlayerName, karena telah menunjukkan kekuranganku.",
  ui_story_30790101_143_dialog_content = "Mulai sekarang, aku akan selalu memperhatikannya.",
  ui_story_30790101_144_dialog_content = "*Michenny pergi*",
  ui_story_30790101_145_dialog_content = "Aduh, kau membiarkannya pergi begitu saja, PlayerName?",
  ui_story_30790101_146_dialog_content = "Hah?",
  ui_story_30790101_147_dialog_content = "Kau seharusnya membayarku karena aku terpeleset.",
  ui_story_30790101_148_dialog_content = "Tapi kau malah membuatnya merasa bersalah dan melepaskan diri dari kewajibanmu.",
  ui_story_30790101_149_dialog_content = "Jangan ungkapkan aku. Apakah kamu benar-benar ingin aku membayar kamu dengan tarif sepuluh Nightium per sentimeter?",
  ui_story_30790101_150_dialog_content = "Kenapa tidak.",
  ui_story_30790101_151_dialog_content = "Aku tidak mau.",
  ui_story_30790601_1_dialog_content = "PlayerName, akhirnya ketemu juga.",
  ui_story_30790601_2_dialog_content = "... Michenny? Saya tidak mengenali kamu dengan outfit itu.",
  ui_story_30790601_3_dialog_content = "Sebenarnya, saya hanya ingin berkonsultasi tentang pakaian saya. Dan saya akan menggantikan waktu Anda.",
  ui_story_30790601_4_dialog_content = "Pakaian? Kompensasi? Apa yang kau bicarakan?",
  ui_story_30790601_5_dialog_content = "Saya berencana pergi ke Rediesel Desert dan berpikir outfit ini akan membantu saya menyatu dengan lingkungan. Bagaimana menurutmu?",
  ui_story_30790601_6_dialog_content = "Apakah saya mendengar dengan benar? Kamu akan pergi ke Rediesel Desert? Bangsawan Lumo jarang sekali pergi ke sana.",
  ui_story_30790601_7_dialog_content = "Tolong, jawab pertanyaan saya—apakah outfit ini oke?",
  ui_story_30790601_8_dialog_content = "Oh, ini lebih dari baik, kamu terlihat hebat.",
  ui_story_30790601_9_dialog_content = "Terima kasih, ini adalah hadiahmu karena telah menjawab pertanyaanku—100 Nightium.",
  ui_story_30790601_10_dialog_content = "Hah? Kamu mau bayar saya hanya untuk menjawab pertanyaan? Tidak, terima kasih.",
  ui_story_30790601_11_dialog_content = "Jadi kamu lebih suka permata? Sayangnya, nilai dari hal ini tidak cukup layak untuk sebuah permata.",
  ui_story_30790601_12_dialog_content = "Uh, tidak... lupakan saja, aku akan ambil uangnya, tapi kamu juga harus menjawab pertanyaan untukku... untuk 100 Nightium.",
  ui_story_30790601_13_dialog_content = "Mengapa kamu pergi ke Gurun Rediesel?",
  ui_story_30790601_14_dialog_content = "Untuk Dunecat ini.",
  ui_story_30790601_15_dialog_content = "Hah?",
  ui_story_30790601_16_dialog_content = "Meong.",
  ui_story_30790601_17_dialog_content = "Apa?! Dari mana kucing itu datang?",
  ui_story_30790601_18_dialog_content = "Saya membawanya ke sini.",
  ui_story_30790601_19_dialog_content = "Sejak kapan kamu punya kucing peliharaan?",
  ui_story_30790601_20_dialog_content = "Ini bukan hewan peliharaan.",
  ui_story_30790601_21_dialog_content = "Kenapa kamu punya itu lalu?",
  ui_story_30790601_22_dialog_content = "Ini tertangkap oleh seorang penyelundup binatang di Gurun Rediesel, dan kepalanya terluka saat penangkapan.",
  ui_story_30790601_23_dialog_content = "Pengedar itu membawanya ke Lumopolis dan menjualnya kepada seorang bangsawan angkuh yang kemudian meninggalkannya di pinggir jalan setelah mengetahui luka di kepala.",
  ui_story_30790601_24_dialog_content = "Saya kebetulan lewat dan melihat apa yang terjadi, jadi saya menangkap baik si bangsawan maupun pengedar itu.",
  ui_story_30790601_25_dialog_content = "Para pengedar binatang sialan itu!",
  ui_story_30790601_26_dialog_content = "Saya telah menjawab empat pertanyaan Anda secara total.",
  ui_story_30790601_27_dialog_content = "O-Oke, saya akan membayar, tapi saat ini saya tidak membawa uang. Saya akan memberi Anda 100 Nightium dulu, dan sisanya...",
  ui_story_30790601_28_dialog_content = "Tidak perlu, standar untuk hal-hal seperti itu tidak tetap, dan saya tidak keberatan melonggarkan aturan saat berurusan dengan orang miskin seperti Anda. Cukup 100 Nightium saja.",
  ui_story_30790601_29_dialog_content = "M-Miskin? Hmm... Aduh, ketahuan, deh...",
  ui_story_30790601_30_dialog_content = "Meong...",
  ui_story_30790601_31_dialog_content = "Melihat aksesoris pada Dunecat ini, saya berasumsi bahwa itu memiliki pemilik, yang pasti sangat cemas sekarang.",
  ui_story_30790601_32_dialog_content = "Jadi, saya perlu mengirimkannya kembali ke gurun secepat mungkin.",
  ui_story_30790601_33_dialog_content = "Aku akan pergi denganmu. Kamu belum pernah ke Gurun Rediesel... Tempatnya cukup berbahaya.",
  ui_story_30790601_34_dialog_content = "Kalau begitu... saya perlu melakukan beberapa perhitungan.",
  ui_story_30790601_35_dialog_content = "Lagi? Kamu bahkan sudah mengeluarkan neraca...",
  ui_story_30790601_36_dialog_content = "Biaya pengawalan, biaya perjalanan, biaya keamanan pribadi, biaya medis, dan nilai tambah menjadi Caelestite terakhir di dunia...",
  ui_story_30790601_37_dialog_content = "Biayanya sedikit terlalu tinggi. Seharusnya mudah untuk menanggung jika hanya patah kaki, tetapi jika kamu kehilangan nyawamu...",
  ui_story_30790601_38_dialog_content = "Mengapa kamu menganggap sesuatu yang buruk akan terjadi padaku?!",
  ui_story_30790601_39_dialog_content = "Penilai harus mempertimbangkan dan mengukur semua situasi dengan tepat.",
  ui_story_30790601_40_dialog_content = "Pikirkan saja itu sebagai teman yang menemani Anda melakukan kebaikan, tanpa biaya atau bahaya!",
  ui_story_30790601_41_dialog_content = "Dengan cara itu, saya perlu menaruh persahabatan di satu ujung timbangan. Itu bahkan lebih berat.",
  ui_story_30790601_42_dialog_content = "Jangan terlalu memikirkan hal-hal ini. Dengan waktu yang kamu habiskan untuk menghitung semua ini, kita seharusnya sudah bisa membawa Dunecat ini pulang sekarang.",
  ui_story_30790601_43_dialog_content = "Memang, saya lupa mempertimbangkan waktu yang dibutuhkan tadi. Terima kasih atas pengingatnya.",
  ui_story_30790601_44_dialog_content = "Baiklah, baiklah! Ayo cepat-cepat berangkat saja.",
  ui_story_30790601_45_dialog_content = "Jadi, ini adalah Gurun Rediesel.",
  ui_story_30790601_46_dialog_content = "Yap. Kamu tahu di mana rumah Dunecat?",
  ui_story_30790601_47_dialog_content = "Tidak.",
  ui_story_30790601_48_dialog_content = "Jadi, bagaimana kita menemukannya?",
  ui_story_30790601_49_dialog_content = "Dunecat seharusnya tahu.",
  ui_story_30790601_50_dialog_content = "Benar, banyak hewan dapat melacak aroma untuk menemukan jalan pulang mereka.",
  ui_story_30790601_51_dialog_content = "Uh, kucing? Duney? Meong-Meong?",
  ui_story_30790601_52_dialog_content = "Zzzz... meong...",
  ui_story_30790601_53_dialog_content = "Michenny, bagaimana kamu menyebut kucing ini, anyway?",
  ui_story_30790601_54_dialog_content = "Panggil saja Dunecat.",
  ui_story_30790601_55_dialog_content = "Tapi aku baru saja memanggilnya dan sama sekali diabaikan... Mungkin kita harus memberinya nama.",
  ui_story_30790601_56_dialog_content = "Memberi nama akan seperti menganggapnya sebagai hewan peliharaan. Hubungan kami hanya setara dengan pengawal ditambah orang yang diawal.",
  ui_story_30790601_57_dialog_content = "Oke. Aku kira kamu benar-benar suka kucing ini.",
  ui_story_30790601_58_dialog_content = "Gagasan tentang \"menyukai\" dapat dengan mudah menimbulkan kebingungan. Penilaian tidak memerlukan perasaan seperti itu.",
  ui_story_30790601_59_dialog_content = "Saya rasa matahari membuat saya pusing... dan teori-teori Anda hanya membuat saya merasa lebih buruk. Saya pikir saya akan pingsan setiap saat.",
  ui_story_30790601_60_dialog_content = "Dunecat, bisakah kamu menemukan rumahmu?",
  ui_story_30790601_61_dialog_content = "Meong... Zzzz...",
  ui_story_30790601_62_dialog_content = "Menggeliat dan kembali tertidur...",
  ui_story_30790601_63_dialog_content = "Dunecats bersifat nokturnal, yang berarti mereka tidur siang dan aktif terutama di malam hari. Sepertinya kita perlu menunggu hingga malam tiba sebelum ia bisa membawa kita ke rumahnya.",
  ui_story_30790601_64_dialog_content = "Saya punya saran—kita bisa minta bantuan dari Sinsa. Dia adalah pemimpin dari Rediesel Wrench.",
  ui_story_30790601_65_dialog_content = "Mungkin mereka bisa membantu kita menemukan rumah Dunecat, atau setidaknya menyediakan kita makanan dan tempat berlindung...",
  ui_story_30790601_66_dialog_content = "Tidak, sebagai seorang bangsawan, saya lebih suka tidak berurusan dengan orang barbar itu.",
  ui_story_30790601_67_dialog_content = "Kamu tidak kenal mereka—mereka sebenarnya orang yang sangat baik, dan kita sangat membutuhkan makanan dan air sekarang.",
  ui_story_30790601_68_dialog_content = "Ibu saya membesarkan saya dengan pelatihan kemandirian sejak saya bayi, dan saya dipilih oleh The Hall of Justice, di antara yang lainnya, karena sikap dewasa dan tenang saya.",
  ui_story_30790601_69_dialog_content = "Jadi, bahkan di sini di gurun, saya percaya saya bisa bertahan tanpa bantuan mereka.",
  ui_story_30790601_70_dialog_content = "Oke, jika itu masalahnya, apa yang kamu usulkan kita lakukan sekarang?",
  ui_story_30790601_71_dialog_content = "Tugas pertama kita seharusnya mencari sumber air. Kita harus mencari oasis atau menggali sumur sendiri.",
  ui_story_30790601_72_dialog_content = "Yang bisa saya lihat di sekitar sini hanyalah lautan pasir yang tak berujung. Tidak ada satu pohon pun, apalagi tanda-tanda keberadaan oasis.",
  ui_story_30790601_73_dialog_content = "Dan bagaimana kita bisa menggali sumur tanpa alat?",
  ui_story_30790601_74_dialog_content = "Kita akan menggali dengan tangan. Ini hanya pasir, setelah semua.",
  ui_story_30790601_75_option_content = "Coba gali di sini",
  ui_story_30790601_76_dialog_content = "Tidak ada apa-apa di sini.",
  ui_story_30790601_77_option_content = "Coba gali lagi",
  ui_story_30790601_78_dialog_content = "Pasir itu runtuh begitu saya mulai menggali.",
  ui_story_30790601_79_option_content = "Rencana gagal...",
  ui_story_30790601_80_dialog_content = "Kita tidak bisa menggali secara buta seperti ini dan berdoa untuk keajaiban. Saya ingat membaca sesuatu tentang ini dalam buku. Jika kamu melihat lumut di gurun, itu berarti ada banyak kelembapan di dekatnya.",
  ui_story_30790601_81_dialog_content = "Hanya dengan menggali di sepanjang area lembab, kita dapat memiliki kesempatan untuk menemukan air tanah.",
  ui_story_30790601_82_dialog_content = "Yang bisa saya lihat di sini hanyalah beberapa tanaman yang terlihat seperti rumput layu—akarnya seharusnya mengandung sedikit kelembapan. Saya akan mencoba mencabut beberapa.",
  ui_story_30790601_83_dialog_content = "Di sini, ini untuk Anda.",
  ui_story_30790601_84_dialog_content = "Kamu yakin bisa makan akar kering ini?",
  ui_story_30790601_85_dialog_content = "Tentu saja, ini adalah tanaman gurun. Pasti mengandung air.",
  ui_story_30790601_86_option_content = "Ambil gigitan",
  ui_story_30790601_87_dialog_content = "Baah, semuanya berpasir.",
  ui_story_30790601_88_option_content = "Rencana gagal...",
  ui_story_30790601_89_dialog_content = "Sudah larut. Jika Dunecat tidak bangun atau luka di kepalanya belum sembuh, kita mungkin perlu menginap di sini.",
  ui_story_30790601_90_dialog_content = "Jadi, kita harus mencari Sin—",
  ui_story_30790601_91_dialog_content = "Kita harus membuat tempat berlindung sederhana, seperti pondok kayu kecil.",
  ui_story_30790601_92_dialog_content = "Sebuah pondok kayu kecil?! Kau serius?",
  ui_story_30790601_93_dialog_content = "Ya. Saya bukan salah satu bangsawan yang sensitif dan tidak masuk akal—yang saya butuhkan hanyalah pondok kayu sederhana.",
  ui_story_30790601_94_dialog_content = "Benar—jika Matthieu ada di sini, dia mungkin akan menyarankan kita untuk membangun rumah emas, sementara kamu hanya ingin kita berdua membangun pondok kayu dengan tangan kosong kita.",
  ui_story_30790601_95_dialog_content = "Satu-satunya kesulitan di sini adalah tidak adanya pohon besar di sekitar.",
  ui_story_30790601_96_dialog_content = "Apakah kamu yakin itu SATU-SATUNYA kesulitan?",
  ui_story_30790601_97_option_content = "Rencana gagal...",
  ui_story_30790601_98_dialog_content = "Bagus, kamu bisa memanggil seseorang dari Rediesel Wrench untuk membantu. Aku akan membayar mereka.",
  ui_story_30790601_99_dialog_content = "Tetapi mereka tidak diperbolehkan memberitahu siapa pun bahwa saya yang mempekerjakan mereka. Ini akan menjadi kesepakatan murni antara majikan dan karyawan yang tidak saling kenal.",
  ui_story_30790601_100_dialog_content = "Bagaimana saya bisa menjelaskan sesuatu seperti itu kepada mereka? Mereka tidak akan menerima pekerjaan dari bangsawan yang sombong dan angkuh. Lupakan saja.",
  ui_story_30790601_101_dialog_content = "Meong...",
  ui_story_30790601_102_dialog_content = "Kucing itu akhirnya bangun!",
  ui_story_30790601_103_dialog_content = "Merasa lebih baik, Dunecat? Bisakah kamu menemukan jalan pulang sekarang?",
  ui_story_30790601_104_dialog_content = "Meong, meong...",
  ui_story_30790601_105_dialog_content = "Ini bisa bergerak perlahan, tetapi sepertinya belum sepenuhnya pulih.",
  ui_story_30790601_106_dialog_content = "Kemudian biarkan berjalan dengan kecepatan sendiri.",
  ui_story_30790601_107_dialog_content = "Mata kamu tidak pernah lepas dari kucing itu meskipun suaramu terdengar sangat acuh tak acuh.",
  ui_story_30790601_108_dialog_content = "Yah, saya tidak ingin itu hilang lagi.",
  ui_story_30790601_109_dialog_content = "Aduh! Aduh, aduh, aduh!",
  ui_story_30790601_110_dialog_content = "Ini kalajengking! Makhluk itu mencubitku dan tidak mau melepaskan!",
  ui_story_30790601_111_dialog_content = "Apa? Apa yang harus kulakukan? A-Aku akan membantu kamu melepaskannya!",
  ui_story_30790601_112_dialog_content = "Tidak, tidak, tidak! Kamu akan merobek kulitku! Aduh! Capitnya semakin erat sekarang!",
  ui_story_30790601_113_dialog_content = "Meong!",
  ui_story_30790601_114_dialog_content = "Hah?! Dunecat itu menepis kalajengking itu dan kalajengking itu langsung melepaskan diri dan lari dalam sekejap!",
  ui_story_30790601_115_dialog_content = "Ini menjilat lukamu, pasti sedang mendisinfeksinya.",
  ui_story_30790601_116_dialog_content = "*menangis* Kamu kucing terbaik di dunia! Kamu menyelamatkan hidupku!",
  ui_story_30790601_117_dialog_content = "...",
  ui_story_30790601_118_dialog_content = "Apakah itu hanya imajinasiku? Dia menggelengkan matanya kepadaku lalu berbalik dan berjalan menjauh...",
  ui_story_30790601_119_dialog_content = "Memang, itu juga tidak tahan dengan kamu.",
  ui_story_30790601_120_dialog_content = "Kalian berdua memberikan tatapan yang sama persis kepadaku sekarang...",
  ui_story_30790601_121_dialog_content = "<color=#e8d9bb>*perut keroncongan*</color>",
  ui_story_30790601_122_dialog_content = "Suara apa itu?",
  ui_story_30790601_123_dialog_content = "Haha, kamu lapar, aku dengar perutmu keroncongan. Tapi aku juga lapar.",
  ui_story_30790601_124_dialog_content = "Apa itu lapar? Saya belum pernah merasa lapar seumur hidup.",
  ui_story_30790601_125_dialog_content = "Perut Anda mengatakan sebaliknya.",
  ui_story_30790601_126_dialog_content = "Tidak, saya adalah bangsawan yang anggun. Saya tidak pernah merasa lapar.",
  ui_story_30790601_127_dialog_content = "<color=#e8d9bb>*groooowwwwl*</color>",
  ui_story_30790601_128_dialog_content = "Lebih keras lagi...",
  ui_story_30790601_129_dialog_content = "S-saya bisa mengambilnya.",
  ui_story_30790601_130_dialog_content = "Meong.",
  ui_story_30790601_131_dialog_content = "Hmm? Kucing itu menangkap... seekor tikus ladang? Dia meletakkannya tepat di depan kamu, seolah-olah mencoba memberimu sesuatu untuk dimakan.",
  ui_story_30790601_132_dialog_content = "Terima kasih, Dunecat, tapi saya benar-benar tidak bisa makan jenis makanan ini.",
  ui_story_30790601_133_dialog_content = "Meong.",
  ui_story_30790601_134_dialog_content = "Meong.",
  ui_story_30790601_135_dialog_content = "Wah! Sebelah sana! Itu Dunecat yang lain!",
  ui_story_30790601_136_dialog_content = "Apakah mereka teman? Mayapakah ini akan membawa kita ke rumah mereka? Mereka berjalan mendekati satu sama lain!",
  ui_story_30790601_137_dialog_content = "Mereka... hah? Mereka hanya mengangguk satu sama lain lalu berpisah?",
  ui_story_30790601_138_dialog_content = "Apakah itu berarti mereka bukan keluarga?",
  ui_story_30790601_139_dialog_content = "Inilah sifat dari Dunecat. Mereka adalah pemburu soliter yang tidak memerlukan kelompok atau rekan. Mereka hanya saling membantu dan berkomunikasi satu sama lain jika diperlukan.",
  ui_story_30790601_140_dialog_content = "Dengan serius... semakin aku melihat, semakin tampaknya kamu dan kucing-kucing Gurun ini persis sama.",
  ui_story_30790601_141_dialog_content = "Meong, meong, meong!!!",
  ui_story_30790601_142_dialog_content = "Apa yang salah, Dunecat?",
  ui_story_30790601_143_dialog_content = "Mengapa mengeluarkan suara itu? Semua bulunya berdiri tegak. Apakah ia merasakan bahaya?",
  ui_story_30790601_144_dialog_content = "Meong!!!",
  ui_story_30790601_145_dialog_content = "Mata itu... Bahaya mengintai di belakang kita!",
  ui_story_30790601_146_dialog_content = "Ini ular!",
  ui_story_30790601_147_dialog_content = "Tidak, itu ular piton besar! Ahhhhh!",
  ui_story_30790601_148_dialog_content = "Jangan takut, Dunecat! Berhenti berjuang! Aku tidak bisa menahannya lagi!",
  ui_story_30790601_149_dialog_content = "Ini menunjukkan giginya pada ular python, seperti mencoba melindungi kamu!",
  ui_story_30790601_150_dialog_content = "Di sini—ambil Dunecat dan lari! Aku akan menghadang python!",
  ui_story_30790601_151_dialog_content = "Bagaimana mungkin aku lari dan meninggalkan kamu? Ayo pergi dari sini bersama-sama!",
  ui_story_30790601_152_dialog_content = "Ular adalah musuh alami Dunecats, jadi pasti akan menyerang. Tolong bawa kucing ini pergi dari sini, cepat! Saya hanya bisa menahannya untuk waktu yang lama!",
  ui_story_30790601_153_dialog_content = "Tunggu sebentar, kita sudah berdiri di sini ngobrol cukup lama, dan ular python ini bahkan belum menyerang kita.",
  ui_story_30790601_154_dialog_content = "Sepertinya agak familiar.",
  ui_story_30790601_155_dialog_content = "itu kamu, PlayerName.",
  ui_story_30790601_156_dialog_content = "Membawa seorang wanita cantik ke tempat seperti ini untuk kencan di tengah malam, itu benar-benar gaya Anda.",
  ui_story_30790601_157_dialog_content = "Apa? Kapan pernah aku melakukan sesuatu yang bahkan mendekati hal itu?",
  ui_story_30790601_158_dialog_content = "Heheh. Hanya bercanda, kok.",
  ui_story_30790601_159_dialog_content = "Sedang apa kau di sini? Ngomong-ngomong, python itu Speakermu, kan?",
  ui_story_30790601_160_dialog_content = "Saya kebetulan lewat di sini ketika Python Suci saya mendeteksi sesuatu yang tidak biasa di sekitar dan datang untuk memeriksanya.",
  ui_story_30790601_161_dialog_content = "Tidak pernah menyangka bahwa itu akan menangkapmu sedang berbuat tidak baik!",
  ui_story_30790601_162_dialog_content = "Bukan begitu. Kita sedang melakukan kebaikan—membantu kucing ini menemukan rumahnya.",
  ui_story_30790601_163_dialog_content = "Hmm, hiasan pada kucing kecil ini sangat spesial. Mereka milik suku yang berada jauh di dalam gurun.",
  ui_story_30790601_164_dialog_content = "Tahu kah kamu di mana rumahnya?",
  ui_story_30790601_165_dialog_content = "Ya. Suku itu sangat misterius dan memiliki sedikit sekali kontak dengan dunia luar. Mereka percaya pada Dewa Gurun, dan menganggap Kucing Pasir sebagai utusan surga.",
  ui_story_30790601_166_dialog_content = "Mereka memilih Dunecat tercantik setiap tahun dan menghiasinya dengan perhiasan, menganggapnya sebagai totem mereka dan simbol suci suku tersebut.",
  ui_story_30790601_167_dialog_content = "Jadi ini kucing yang sangat penting. Bisakah kamu bawa kami ke suku kucingnya?",
  ui_story_30790601_168_dialog_content = "Sayangnya, tidak. Suku itu cukup bermusuhan terhadap orang asing. Bagaimana Anda menemukan Dunecat ini?",
  ui_story_30790601_169_dialog_content = "Michenny menangkap penyelundup jahat yang mencuri kucing ini di Lumopolis.",
  ui_story_30790601_170_dialog_content = "Jadi, itu dicuri. Dalam hal ini, kamu tidak bisa langsung pergi ke suku tersebut, karena mungkin akan menimbulkan kesalahpahaman yang tidak menyenangkan dan tidak perlu.",
  ui_story_30790601_171_dialog_content = "Aku akan bawa Dunecat kembali. Aku masih punya beberapa hubungan dengan mereka, dan mereka akan percaya apa yang aku katakan.",
  ui_story_30790601_172_dialog_content = "Itu terdengar seperti ide yang cemerlang! Bagaimana menurutmu, Michenny?",
  ui_story_30790601_173_dialog_content = "Orang ini... Bisakah kita benar-benar mempercayainya dengan kucing?",
  ui_story_30790601_174_dialog_content = "Jeriah adalah anggota senior dari Courier Union, dan dia juga teman saya. Kita pasti bisa mempercayai dia.",
  ui_story_30790601_175_dialog_content = "Betapa tajamnya pengamatanmu! Kamu bisa langsung tahu bahwa aku sama sekali tidak bisa diandalkan!",
  ui_story_30790601_176_dialog_content = "Jangan marah, Jeriah. Michenny hanya saja—",
  ui_story_30790601_177_dialog_content = "Oke, tenangkan dirimu. Kamu harus tahu bahwa aku tidak terlalu sensitif.",
  ui_story_30790601_178_dialog_content = "... Baik. Tolong pastikan kamu mengembalikannya dengan aman. Aku akan membayar kamu.",
  ui_story_30790601_179_dialog_content = "Gadis kecil yang menawan. Meskipun ia berpakaian untuk gurun, ia berbicara seolah-olah ia berada di Lumopolis.",
  ui_story_30790601_180_dialog_content = "Karena kamu telah mempercayakan pekerjaan ini padaku, mari kita anggap ini sebagai urusan resmi Courier Union.",
  ui_story_30790601_181_dialog_content = "Tapi saya harus menaruhnya di samping untuk saat ini, sampai saya punya waktu untuk mengantarkannya.",
  ui_story_30790601_182_dialog_content = "Tidak mungkin! Kucing ini terluka! Dia harus kembali ke keluarganya segera!",
  ui_story_30790601_183_dialog_content = "Aku akan membayar kamu lebih... sebanyak yang kamu inginkan.",
  ui_story_30790601_184_dialog_content = "Jeriah, aku tahu kamu biasanya tidak mengerjakan pekerjaan seperti ini, tetapi urusan kucing ini adalah situasi yang cukup spesial. Silahkan...",
  ui_story_30790601_185_dialog_content = "Jika itu permintaan dari teman, tentu saja saya bisa memprioritaskannya. Tapi jika itu pekerjaan...",
  ui_story_30790601_186_dialog_content = "T-Tolong anggap ini sebagai permintaan dari seorang teman. Meskipun aku tidak tahu apakah kamu bersedia melihatku sebagai teman...",
  ui_story_30790601_187_dialog_content = "Jadi, wanita bangsawan yang sombong ini bersedia melepaskan statusnya. Sepertinya kamu benar-benar peduli pada kucing kecil ini.",
  ui_story_30790601_188_dialog_content = "Tolong, Jeriah! Tolong bantu kami mengantarkan kucing ini ke rumahnya. Aku akan—",
  ui_story_30790601_189_option_content = "Pakai rok!",
  ui_story_30790601_190_dialog_content = "Oh... Aku tidak percaya kamu mau pergi sejauh itu...",
  ui_story_30790601_191_dialog_content = "Heheh, tidak mungkin aku melewatkan kesempatan seperti ini.",
  ui_story_30790601_192_dialog_content = "Apa yang baru saja aku katakan?! Bagaimana bisa aku mengeluarkan kata-kata seperti itu...",
  ui_story_30790601_193_option_content = "Meong seperti kucing!",
  ui_story_30790601_194_dialog_content = "Biarkan aku mendengar. Mari kita lihat apakah kamu ahli bahasa kucing alami.",
  ui_story_30790601_195_dialog_content = "Meong... meong, meong... meong... Ini memalukan...",
  ui_story_30790601_196_dialog_content = "Hehe, lumayan imut.",
  ui_story_30790601_197_dialog_content = "Itu sangat memalukan, PlayerName, tetapi baik kucing dan saya sangat berterima kasih kepada Anda.",
  ui_story_30790601_198_dialog_content = "Ini tidak apa-apa, semua untuk kucing... *isak*",
  ui_story_30790601_199_dialog_content = "Baik, saya akan membawa kucing kembali dengan selamat dalam waktu singkat.",
  ui_story_30790601_200_dialog_content = "Bagus! Trims!",
  ui_story_30790601_201_dialog_content = "Terima kasih.",
  ui_story_30790601_202_dialog_content = "Jadi, Michenny, saatnya untuk mengucapkan selamat tinggal pada kucing.",
  ui_story_30790601_203_dialog_content = "Tolong izinkan saya untuk memeluknya satu kali lagi.",
  ui_story_30790601_204_dialog_content = "Meooong!",
  ui_story_30790601_205_dialog_content = "Kitty, semoga kamu cepat sembuh. Aku akan merindukanmu.",
  ui_story_30790601_206_dialog_content = "(Michenny memeluk Dunecat dalam pelukannya untuk waktu yang lama, enggan melepaskannya. Matanya berkilau seperti ada air mata.)",
  ui_story_30790601_207_dialog_content = "michenny...",
  ui_story_30790601_208_dialog_content = "Aku baik-baik saja.",
  ui_story_30790601_209_dialog_content = "Selamat tinggal, Dunecat.",
  ui_story_30790601_210_dialog_content = "Meong."
}
return config
